class Solution {
  public int maxValue(int[] nums1, int[] nums0) {
    final long MOD = 1_000_000_007L;
    int n = nums1.length, maxLen = 0;
    for (int i = 0; i < n; i++) maxLen = Math.max(maxLen, nums1[i] + nums0[i]);
    long[] pow2 = new long[maxLen + 2];
    pow2[0] = 1;
    for (int i = 1; i < pow2.length; i++) pow2[i] = pow2[i - 1] * 2 % MOD;
    List<int[]> allOnes = new ArrayList<>(),
        mixed = new ArrayList<>(),
        allZeros = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      int[] seg = {nums1[i], nums0[i]};
      if (nums1[i] == 0) allZeros.add(seg);
      else if (nums0[i] == 0) allOnes.add(seg);
      else mixed.add(seg);
    }
    mixed.sort((a, b) -> a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(a[1], b[1]));
    long result = 0;
    List<int[]> order = new ArrayList<>(allOnes);
    order.addAll(mixed);
    order.addAll(allZeros);
    for (int[] seg : order) {
      long value = (pow2[seg[0]] - 1 + MOD) % MOD * pow2[seg[1]] % MOD;
      int len = seg[0] + seg[1];
      result = (result * pow2[len] + value) % MOD;
    }
    return (int) result;
  }
}
